package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Arrays;
import java.util.Locale;
import java.util.stream.Collectors;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: the amount is required, a
 *  number with up to two decimals, below 0.00 only for a correction, which names (by its number: a whole number, or <period name>-<n> / X-<n>) the claim it
 *  corrects, and only a correction names one; the date, when given, is a real yyyy-mm-dd date; a reference, when given, is
 *  at most 200 characters (whether it is already used on the sheet is checked once the sheet is read); tags, when given, are at most
 *  1000 characters once normalised. */
public class ValidateClaim {
    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> body) throws InvalidClaimException {
        body.set(check(request));
    }

    /** The claim form's rules, shared by every way a claim is added (the paste box checks each line by them). */
    static ClaimInput check(ClaimRequest request) throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before changing claims.");
        }
        String amount = request.amount() == null ? "" : request.amount().trim();
        if (amount.isEmpty()) {
            throw new InvalidClaimException("An amount is required.");
        }
        if (!amount.matches("-?\\d{1,12}(\\.\\d{1,2})?")) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        String rawCorrects = request.corrects() == null ? "" : request.corrects().trim();
        String corrects = null;
        if (!rawCorrects.isEmpty()) {
            if (rawCorrects.matches("\\d{1,9}")) {
                corrects = String.valueOf(Integer.parseInt(rawCorrects));
            } else if (rawCorrects.matches(".{1,200}-\\d{1,9}")) {
                corrects = rawCorrects;
            } else {
                throw new InvalidClaimException("The claim corrected must be named by its number.");
            }
        }
        if (value.signum() < 0 && corrects == null) {
            throw new InvalidClaimException(
                    "A negative amount is a correction: name the number of the SETTLED claim it corrects.");
        }
        if (value.signum() >= 0 && corrects != null) {
            throw new InvalidClaimException("Only a correction (a negative amount) names a claim it corrects.");
        }
        String rawDate = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!rawDate.isEmpty()) {
            if (!rawDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
                throw new InvalidClaimException("The date must be a date (yyyy-mm-dd).");
            }
            try {
                date = LocalDate.parse(rawDate);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("The date must be a real date (yyyy-mm-dd).");
            }
        }
        String note = request.note() == null ? "" : request.note().trim();
        if (note.length() > 1000) {
            throw new InvalidClaimException("A note is at most 1000 characters.");
        }
        String ref = request.ref() == null ? "" : request.ref().trim();
        if (ref.length() > 200) {
            throw new InvalidClaimException("A reference is at most 200 characters.");
        }
        String tags = request.tags() == null ? null : tags(request.tags());
        if (tags != null && tags.length() > 1000) {
            throw new InvalidClaimException("Tags are at most 1000 characters.");
        }
        return new ClaimInput(request.user().trim(), value, date, note, corrects, ref.isEmpty() ? null : ref, tags);
    }

    /** Tags as typed, separated by commas: each trimmed and lower-cased, blanks and repeats dropped, sorted and joined
     *  by commas ("" when none). */
    static String tags(String typed) {
        return Arrays.stream(typed.split(",")).map(t -> t.trim().toLowerCase(Locale.ROOT)).filter(t -> !t.isEmpty())
                .distinct().sorted().collect(Collectors.joining(","));
    }
}
package net.officefloor.hq.app.claim;

/** Body of a claim add or edit: who is making it, the amount as typed, the date (blank for the
 *  sheet's today), the note and, for a correction, the number of the claim it corrects (blank otherwise), and its
 *  external reference (blank or absent: none), and its tags
 *  as typed, separated by commas (blank: none; absent: an edit keeps the ones it has). */
public record ClaimRequest(String user, String amount, String date, String note, String corrects, String ref, String tags) {
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated claim add or edit. The date is null when the sheet's today is to be used; corrects is the
 *  number of the claim a correction (a negative amount) corrects, null for any other claim; ref is its external
 *  reference, trimmed (null: none); tags are its tags, normalised and joined by commas ("": none; null: not
 *  given, so an edit keeps the ones it has). */
public record ClaimInput(String user, BigDecimal amount, LocalDate date, String note, String corrects, String ref, String tags) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Record the stored add in the audit file, with the amount and date as the screen shows them, and its reference and its tags when it has them. */
public class AuditClaimAdded {
    public void audit(@Val ClaimInput input, @Val Person person, @Val Claim claim, Audit audit) {
        record(input, person, claim, audit);
    }

    /** The CLAIM_ADDED line for one stored add, then LATE_ENTRY for a late entry (the paste box writes one per line it adds). */
    static void record(ClaimInput input, Person person, Claim claim, Audit audit) {
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("CLAIM_ADDED sheet=" + claim.sheetId() + " by=" + input.user()
                + " person=" + person.name() + " amount=" + shown.amount() + " date=" + shown.date()
                + (claim.ref() != null ? " ref=" + claim.ref() : "")
                + (claim.tags() != null ? " tags=" + claim.tags() : ""));
        if (claim.lateEntry()) {
            audit.record("LATE_ENTRY sheet=" + claim.sheetId() + " by=" + input.user()
                    + " person=" + person.name() + " amount=" + shown.amount() + " date=" + shown.date());
        }
    }
}
