import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A reason on the sheet's list of void reasons, with how many VOID claims were voided with it. */
export type VoidReason = { id: number; reason: string; by: string; voided: number };

export const voidReasonsKey = (sheetId: string) => ['sheet', sheetId, 'void-reasons'] as const;

/** The sheet's void reasons, in the order they were added. */
export function useVoidReasons(sheetId: string) {
  return useQuery({
    queryKey: voidReasonsKey(sheetId),
    queryFn: () => getJson<VoidReason[]>(`/api/sheets/${encodeURIComponent(sheetId)}/void-reasons`),
  });
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetBody } from '../../slots/defs/sheet';
import { useVoidReasons, voidReasonsKey } from './voidreasons';
import type { VoidReason } from './voidreasons';

function VoidReasonList({ sheetId }: { sheetId: string }) {
  const reasons = useVoidReasons(sheetId).data ?? [];
  return (
    <ul>
      {reasons.map((r) => (
        <li key={r.id} data-testid={`void-reason-row-${r.reason}`}>
          {r.reason}
        </li>
      ))}
    </ul>
  );
}

function VoidReasonForm({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const [reason, setReason] = useState('');
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (r: string) =>
      postJson<VoidReason>(`/api/sheets/${encodeURIComponent(sheetId)}/void-reasons`, { user, reason: r }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: voidReasonsKey(sheetId) });
      setReason('');
    },
    onError: (e) => setError(e instanceof HttpError && e.body ? e.body : 'Could not add the void reason.'),
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (reason.trim() === '') {
      setError('Give the void reason.');
      return;
    }
    if (!once.start()) return;
    save.mutate(reason.trim());
  };

  return (
    <form data-testid="void-reason-form" onSubmit={submit}>
      <input
        data-testid="void-reason-text"
        placeholder="Void reason"
        value={reason}
        onChange={(e) => {
          setReason(e.target.value);
          setError('');
        }}
      />{' '}
      <button type="submit" data-testid="void-reason-add" disabled={save.isPending}>
        Add void reason
      </button>
      {error && (
        <p data-testid="void-reason-error" role="alert">
          {error}
        </p>
      )}
    </form>
  );
}

/** The sheet's void reasons and the entry a reason is added with. While the list is not empty, a claim is voided
 *  only with a reason chosen from it. */
function VoidReasons({ sheetId, user }: { sheetId: string; user: string }) {
  return (
    <section data-testid="void-reasons">
      <h2>Void reasons</h2>
      <VoidReasonForm sheetId={sheetId} user={user} />
      <VoidReasonList sheetId={sheetId} />
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 7.6, Component: VoidReasons });
